/** A05-AUTORIZACIONES: indexado por KEY-AUTS151 (autorización S500 de Red Extendida). */
@Entity
@Table(name = "autorizacion_red_extendida")
public class AutorizacionRedExtendida {

    @Id
    private long autS500Ext;                 // R01-REG-AUTS500EXT 9(08)
    private long autAElim;                   // R01-REG-AUTAELIM: autorización que esta elimina
    private long autAntS151;                 // R01-REG-AUTANTS151: cadena de autorizaciones previas
    private int tipoProceso;

    @ElementCollection
    @OrderColumn(name = "slot")
    @Size(max = 5)                           // OCCURS 5 TIMES
    private List<Transaccion> transacciones;

    private int tipoMedioAcceso;             // 500TIPMDA
    private String medioAcceso;              // 500MEDACC 9(16): String para conservar ceros
    private int moneda;                      // 500MONEDA: 1 pesos, 5 dólares en P054
    private String referenciaNumerica;       // 500REFNUM 9(12)
    @Size(max = 5) private List<String> leyendas;       // 5 x X(40)
    @Size(max = 3) private List<String> refAdicionales; // 3 x X(35)

    private long numAutoriza;
    private Sucursal operadora;              // NUMSUCOPE + NUMCAJOPE: donde se captura
    private Sucursal transactora;            // NUMSUCTRA + NUMCAJTRA: donde se aplica
    private LocalTime horaMovimiento;        // R01-REG-HORMOV 9(06) HHMMSS
    @Enumerated(EnumType.ORDINAL)
    private StatusAutorizacion status;       // 2, 3 y 4 los asigna 400030-ACTUALIZA-STATUS

    @Embeddable
    public record Transaccion(int cveTran, int indLey,
                              @Digits(integer = 16, fraction = 2) BigDecimal importe) {}   // 9(16)V99 COMP
    @Embeddable
    public record Sucursal(int sucursal, int caja) {}
}

@Component
@RequiredArgsConstructor
class CorteScheduler {

    private final GeneradorRedExtendida generador;   // 030300-GENERA-ARCHIVO
    private final Clock clock;
    private LocalDate fechaAnterior;                 // WKS-FECHA-MAQ-ANT-8D

    /** Reemplaza el despertar de ESPERACOMS: cada vuelta intenta generar, haya o no mensaje. */
    @Scheduled(fixedDelayString = "${p054.ciclo.espera:PT60S}")
    void despierta() {
        LocalDate hoy = LocalDate.now(clock);
        if (!hoy.equals(fechaAnterior)) {
            fechaAnterior = hoy;
            // El fuente calcula W77-HABIL con THECALENDAR FUN 18, pero ningún párrafo lo consulta.
            // No se traduce como condición para no introducir un comportamiento que P054 no tiene.
        }
        generador.generaYEnviaSiCorresponde(hoy);
    }
}

@Service
@RequiredArgsConstructor
class CortesEnvio {

    private final CatalogoCortes catalogo1822;   // WKS-HORA-CORTE OCCURS 1000, HHMM
    private int indiceVigente;                    // W77-IND-ENV, persistido en A03-CTL-ENVIO

    /** 030302-VERIFICA-ENVIO. */
    Decision evalua(LocalTime ahora, boolean envioPendiente) {
        Optional<LocalTime> corte = catalogo1822.corte(indiceVigente);   // vacío = 9999
        if (corte.isEmpty()) {
            return Decision.TERMINA_DIA;          // MOVE 1 TO WKS-ARCH-GEN y 999999-FIN
        }
        boolean alcanzado = !ahora.truncatedTo(ChronoUnit.MINUTES).isBefore(corte.get());
        return (alcanzado || envioPendiente) ? Decision.GENERA_Y_ENVIA : Decision.SOLO_GENERA;
    }
}

@MessagingGateway
interface IntelarGateway {
    @Gateway(requestChannel = "intelarSalida")
    void envia(Path archivo);                        // INTELARSND IN ADMONXFERS
}

@Service
@RequiredArgsConstructor
class EnvioRedExtendida {

    private final IntelarGateway intelar;
    private final ControlEnvioRepository control;     // A03-CTL-ENVIO

    @Transactional
    void envia(ArchivosCorte archivos) {
        intelar.envia(archivos.pesos());
        intelar.envia(archivos.dolares());
        // Solo si ambos envíos terminaron se limpian trailer y totales (400021-LIMPIA-*).
        // En el fuente un error de INTELAR se registra en LJ y la limpieza ocurre igual.
        control.limpiaTotalesYAvanzaCorte();
    }
}

@Bean
IntegrationFlow movimientosS500(MovimientoS500Reader lector,      // A01-MOVS500 desde W77-AUT-ENVIO500 + 1
                                DatosAdicionales a02,             // A02-DESS500 por APUDES
                                DetalleExtnetTransformer detalle,
                                CancelacionHandler cancelaciones) {
    return IntegrationFlow.from(lector)
            .enrich(e -> e.requestPayload(m -> a02.indicadorExtnet((MovimientoS500) m.getPayload()))
                          .propertyFunction("indExtnet", m -> m.getPayload()))
            .<MovimientoS500, String>route(m -> clasifica(m), r -> r
                    .subFlowMapping("ALTA", f -> f.handle(detalle))
                    .subFlowMapping("CANCELA", f -> f.handle(cancelaciones::porAutorizacion))
                    .subFlowMapping("CANCELA_PROCESO", f -> f.handle(cancelaciones::porProceso))
                    .subFlowMapping("CANCELA_PROCESO_AUT", f -> f.handle(cancelaciones::porProcesoAut))
                    .defaultOutputToParentFlow())          // NEXT SENTENCE: se ignora
            .get();
}

static String clasifica(MovimientoS500 m) {
    if (m.sistema() != 500) return "IGNORA";
    return switch (m.funcion()) {
        case 1 -> (Set.of(1, 2, 3, 4).contains(m.status()) && Set.of(1, 3).contains(m.origen())
                   && m.formato() == 2 && m.indExtnet() == 3) ? "ALTA" : "IGNORA";
        case 2  -> "CANCELA";
        case 21 -> "CANCELA_PROCESO";
        case 22 -> "CANCELA_PROCESO_AUT";
        default -> "IGNORA";   // la función 99 marca fin de archivo y no llega aquí
    };
}

@Component
@RequiredArgsConstructor
class DetalleExtnetTransformer {

    private static final int CLAVE_SIEMPRE_ABONO = 1009;   // p054.clave-abono-forzado
    private final Catalogo6 cat6;                           // WKS-CAT6-AFC(1..5000)
    private final Catalogo1823 cat1823;                     // WKS-CVETRAN-EXTNET-1 OCCURS 5000

    /** 400040-MUEVE-DATOS-EXTNET: solo la primera clave del movimiento (UNTIL W77-IND > 1). */
    Optional<DetalleExtnet> transforma(MovimientoS500 m) {
        int clave = m.cveTran(1);
        int afc = (clave > 0 && clave < 5001) ? cat6.afc(clave) : 0;   // 1 cargo, 2 abono, 9 no contable
        if (clave == CLAVE_SIEMPRE_ABONO) afc = 2;

        if (m.moneda() != 1 && m.moneda() != 5) return Optional.empty();
        Catalogo1823.Entrada e = cat1823.entrada(clave)
                .orElseThrow(() -> new ClaveFueraDeCatalogoException(clave));   // el fuente no valida el rango
        if (e.envioCamelia() != 2) return Optional.empty();

        int claveEnvio = (e.transforma() != 2) ? clave
                : switch (afc) {
                    case 1 -> e.claveCargo();        // CLVTRAC
                    case 2, 9 -> e.claveAbono();     // CLVTRAA
                    default -> clave;
                };
        return Optional.of(DetalleExtnet.desde(m, 1, claveEnvio, afc));   // 400022-CARGA-DATOS-EXTNET
    }
}

# application.yml  (antes: literales en 400022-CARGA-DATOS-EXTNET)
p054:
  detalle:
    sucursal: 4000
    caja-por-csi: { "10": 1, "32": 1, default: 2 }

// ---------------------------------------------------------------------------
static DetalleExtnet desde(MovimientoS500 m, int slot, int claveEnvio, int afc, DetalleProperties p) {
    var medio = switch (m.cveMda()) {                    // tipo de medio de acceso
        case 0 -> MedioAcceso.contrato(m.sucProm(), m.contrato());
        case 1 -> MedioAcceso.cuenta(m.mdaSuc(), m.mdaCta());
        case 2 -> MedioAcceso.directo(m.mdaCta());
        default -> MedioAcceso.vacio();                  // el fuente deja el campo en ceros
    };
    return new DetalleExtnet(
            m.autS151(),                                 // SECDET y NUMAUT = A00-R01-AUT-S151
            p.sucursal(), p.caja(m.csiHost()),
            claveEnvio, afc, m.cveMda(), medio,
            Importe.aPic14v99(m.importe(slot)),          // 9(16)V99 a 9(14)V99, ver riesgo
            m.moneda(), m.refNum(), m.indLey(slot));
}

    /** Sub-registro REFADIC4: autorización, sucursal operadora y transactora, hora original. */
    record IdentidadAutorizacion(long numAutoriza,                // "AU"
                                 int sucOpe, int cajOpe,          // "OP"
                                 int sucTra, int cajTra,          // "TR"
                                 LocalTime horaMovimiento) {}

@Component
@RequiredArgsConstructor
class DetalleExtnetWriter {

    private final ClassifierCompositeItemWriter<DetalleExtnet> porMoneda;   // A04 pesos / A04-D dólares
    private final TotalesCorte totales;                                     // A03-CTL-ENVIO

    void escribe(DetalleExtnet d) throws Exception {
        switch (d.moneda()) {
            case 1 -> totales.pesos().acumula(d.afc(), d.importe());     // 040040-ACUMULA-TOTALES
            case 5 -> totales.dolares().acumula(d.afc(), d.importe());   // 040040-ACUMULA-TOTALES-DOLAR
            default -> { return; }
        }
        porMoneda.write(Chunk.of(d));
    }
}

@Component
@RequiredArgsConstructor
class CancelacionHandler {

    private final AutorizacionRepository a05;
    private final DetalleExtnetWriter writer;

    /** 400040-ELIM-EXTNET + 400030-ACTUALIZA-STATUS. */
    @Transactional
    void porAutorizacion(MovimientoS500 m) {
        a05.findById(m.autAElimS151()).ifPresent(aut -> {       // W88-EXISTE-MOV-EXT
            writer.escribe(DetalleExtnet.cancelacion(aut));      // solo la primera transacción
            aut.setStatus(switch (m.funcion()) {
                case 2  -> StatusAutorizacion.CANCELADA;          // 2
                case 21 -> StatusAutorizacion.CANCELADA_PROCESO;  // 3
                case 22 -> StatusAutorizacion.CANCELADA_PROCESO_AUT; // 4
                default -> aut.getStatus();
            });
            long previa = aut.getAutAntS151();
            while (previa > 0) {                                  // 400020-ELIMINA-AUT-ANTERIORES
                previa = eliminaPrevia(previa);
            }
        });
    }
}

// application.yml: p054.cancelacion.clave: 534   p054.cancelacion.afc: 9
static DetalleExtnet cancelacion(AutorizacionRedExtendida aut, CancelacionProperties p) {
    var t = aut.getTransacciones().get(0);
    if (aut.getMoneda() != 1 && aut.getMoneda() != 5) return null;
    if (cat1823.entrada(t.cveTran()).map(Catalogo1823.Entrada::envioCamelia).orElse(0) != 2) return null;
    // El fuente tenía la transformación a clave de cargo o abono según la naturaleza,
    // pero está comentada: toda eliminación sale con clave 534 y naturaleza 9.
    return DetalleExtnet.eliminacion(aut, p.clave(), p.afc());
}
